mapper.select:
/* MasterOrderMapper.selectMasterOrderChkEms : Ems전자상거래 마스터오더 저장체크 */ SELECT MAX(od.MBL_NO) AS MBL_NO ,MAX(od.FINISH_YN) AS FINISH_YN ,MAX(CASE obl.BL_TYPE_MH WHEN 'M' THEN obl.ORIG_CODE END) AS ORIG_CODE ,MAX(obl.OB_DATE) AS OB_DATE ,MAX(obl.AR_DATE) AS AR_DATE ,COUNT(CASE obl.BL_TYPE_MH WHEN 'H' THEN 1 END) AS HOUSE_CNT ,MAX(obl.DEST_CODE) AS DEST_CODE
,(SELECT COUNT(*) FROM TB_COM_OD_CHG_INVOICE WHERE OD_JOB_NO = A.MASTER_OD_JOB_NO AND INVOICE_JOB_NO IS NOT NULL) AS INVOICE_CNT
,CONVERT(DATE, #{obDate}, ${dateFormat}) AS INPUT_OB_DATE
,CONVERT(DATE, #{arDate}, ${dateFormat}) AS INPUT_AR_DATE
FROM TB_COM_OD od INNER JOIN TB_COM_OBL obl ON od.OBL_JOB_NO = obl.OBL_JOB_NO WHERE obl.MBL_JOB_NO = #{oblJobNo}

mapper.update:
/* MasterOrderMapper.updateHouseOrderBatch : 전자상거래 마스터오더 저장 후 하우스오더 업데이트 */
	UPDATE TB_ECM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))

		  ,LINE_CODE = #{lineCode}
		  ,LINE_NAME = #{lineName}


		  ,VOYAGE = #{vesselVoyage}

		  ,VESSEL_FLIGHT = #{vesselFlight}
		  ,OB_DATE = #{obDate}
		  ,DEST_CODE = #{destCode}
		  ,DEST_NAME = #{destName}
		  ,AR_DATE = #{arDate}
		  ,DEST_COUNTRY = #{destCountry}
		  ,CONSIGNEE_COUNTRY_CODE = #{consigneeCountryCode}

		  ,AMOUNT_LOC = #{amountLoc}
		  ,AMOUNT_USD = #{amountUsd}
		  ,EXCHANGE_RATE = #{exchangeRate}


		  ,ORIG_CODE = #{origCode}
		  ,ORIG_NAME = #{origName}

		  ,ORIG_COUNTRY = #{origCountry}

		  ,SHIPPER_COUNTRY_CODE = #{shipperCountryCode}



		  	,SHIPPER_FAX = #{shipperFax}
		  	,CONSIGNEE_FAX = #{consigneeFax}


		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
	WHERE OD_JOB_NO = #{odJobNo};

