/* MasterOrderMapper.selectHts : 전자상거래 마스터오더 TB_EDI_MF_HTS 조회 */
	SELECT HTS_CODE
	FROM TB_EDI_MF_HTS
	WHERE MF_JOB_NO = #{srchOblJobNo}

/* MasterOrderMapper.selectCntrType : 전자상거래 마스터오더 TB_COM_OBL_CNTR_TYPE 조회 */
	SELECT 
		 CNTR_CODE
		,PIECES
	FROM TB_COM_OBL_CNTR_TYPE
	WHERE OBL_JOB_NO = #{srchOblJobNo}

