/* MasterOrderMapper.updateMasterObl : 전자상거래 마스터오더 TB_COM_OBL 저장 */
	UPDATE TB_COM_OBL SET
		   BL_TYPE_SC = #{blTypeSc}
		  ,MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,CARGO_BL_NO = #{cargoBlNo}
		  ,SHIPPER_CODE = #{shipperCode}
		  ,SHIPPER_NAME = #{shipperName}
		  ,SHIPPER_ADDRESS = SUBSTRING(ISNULL(CAST(UPPER(#{shipperAddress}) AS NVARCHAR(300)), ''), 1, 60)
		  ,SHIPPER_ADDRESS_A = SUBSTRING(ISNULL(CAST(UPPER(#{shipperAddress}) AS NVARCHAR(300)), ''), 61, 60)
		  ,SHIPPER_ADDRESS_B = SUBSTRING(ISNULL(CAST(UPPER(#{shipperAddress}) AS NVARCHAR(300)), ''), 121, 60)
		  ,SHIPPER_ADDRESS_C = SUBSTRING(ISNULL(CAST(UPPER(#{shipperAddress}) AS NVARCHAR(300)), ''), 181, 60)
		  ,SHIPPER_ADDRESS_D = SUBSTRING(ISNULL(CAST(UPPER(#{shipperAddress}) AS NVARCHAR(300)), ''), 241, 60)
		  ,SHIPPER_TEL = #{shipperTel}
		  ,SHIPPER_ZIPCODE = #{shipperZipcode}
		  ,SHIPPER_COUNTRY_CODE = #{shipperCountryCode}
		  ,SHIPPER_STATE_CODE = #{shipperStateCode}
		  ,SHIPPER_PLACE = #{shipperPlace}
		  ,SHIPPER_STREET = #{shipperStreet}
		  ,SHIPPER_BUSINESS_ID = dbo.Cryptography(#{oblJobNo}, #{shipperBusinessId}, 0)
		  ,SHIPPER_ATTN = #{shipperAttn}
		  ,SHIPPER_FAX = #{shipperFax}
		  ,CONSIGNEE_CODE = #{consigneeCode}
		  ,CONSIGNEE_NAME = #{consigneeName}
		  ,CONSIGNEE_ADDRESS = SUBSTRING(ISNULL(CAST(UPPER(#{consigneeAddress}) AS NVARCHAR(300)), ''), 1, 60)
		  ,CONSIGNEE_ADDRESS_A = SUBSTRING(ISNULL(CAST(UPPER(#{consigneeAddress}) AS NVARCHAR(300)), ''), 61, 60)
		  ,CONSIGNEE_ADDRESS_B = SUBSTRING(ISNULL(CAST(UPPER(#{consigneeAddress}) AS NVARCHAR(300)), ''), 121, 60)
		  ,CONSIGNEE_ADDRESS_C = SUBSTRING(ISNULL(CAST(UPPER(#{consigneeAddress}) AS NVARCHAR(300)), ''), 181, 60)
		  ,CONSIGNEE_ADDRESS_D = SUBSTRING(ISNULL(CAST(UPPER(#{consigneeAddress}) AS NVARCHAR(300)), ''), 241, 60)
		  ,CONSIGNEE_TEL = #{consigneeTel}
		  ,CONSIGNEE_ZIPCODE = #{consigneeZipcode}
		  ,CONSIGNEE_COUNTRY_CODE = #{consigneeCountryCode}
		  ,CONSIGNEE_STATE_CODE = #{consigneeStateCode}
		  ,CONSIGNEE_PLACE = #{consigneePlace}
		  ,CONSIGNEE_STREET = #{consigneeStreet}
		  ,CONSIGNEE_BUSINESS_ID = dbo.Cryptography(#{oblJobNo}, #{consigneeBusinessId}, 0)
		  ,CONSIGNEE_ATTN = #{consigneeAttn}
		  ,CONSIGNEE_FAX = #{consigneeFax}
		  ,NOTIFY_CODE = #{notifyCode}
		  ,NOTIFY_NAME = #{notifyName}
		  ,NOTIFY_ADDRESS = SUBSTRING(ISNULL(CAST(UPPER(#{notifyAddress}) AS NVARCHAR(300)), ''), 1, 60)
