		  ,NOTIFY_ADDRESS_B = SUBSTRING(ISNULL(CAST(UPPER(#{notifyAddress}) AS NVARCHAR(300)), ''), 121, 60)
		  ,NOTIFY_ADDRESS_C = SUBSTRING(ISNULL(CAST(UPPER(#{notifyAddress}) AS NVARCHAR(300)), ''), 181, 60)
