/* MasterOrderMapper.updateMasterOblRealDeliverer : 전자상거래 마스터오더 TB_COM_OBL_REAL_DELIVERER 저장      예전데이터는 TB_COM_OBL_REAL_DELIVERER가 없어서 MERGE사용 */
	MERGE TB_COM_OBL_REAL_DELIVERER AS A 
	USING (SELECT #{oblJobNo} AS OBL_JOB_NO) AS B 
	ON (A.OBL_JOB_NO = B.OBL_JOB_NO)  
	WHEN MATCHED THEN
	UPDATE SET
		   HANDLING_SPECIAL_NAME = #{handlingSpecialName}
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHEN NOT MATCHED BY TARGET THEN
	INSERT(
		   OBL_JOB_NO
		  ,ENT_CODE
		  ,ENT_BUSINESS_CODE
		  ,HANDLING_SPECIAL_NAME
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{oblJobNo}
		  ,#{entCode}
		  ,#{entBusinessCode}
		  ,#{handlingSpecialName}
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	);

/* MasterOrderMapper.updateMasterOrder : 전자상거래 마스터오더 TB_COM_OD 저장 */
	UPDATE TB_COM_OD SET
		   MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))


		  ,ORIG_DEST_CODE = #{destCode}
		  ,OBAR_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})


		  ,ORIG_DEST_CODE = #{origCode}
		  ,OBAR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})




		  ,BOOKING_DATE = CONVERT(DATE, #{bookingDate}, ${dateFormat})


		  ,BOOKING_DATE = NULL


		  ,BOOKING_NO = #{bookingNo}
		  ,REMARKS = #{remarks}
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE OD_JOB_NO = #{odJobNo}

