		  ,OB_DATE = CONVERT(DATE, #{obDate},  ${dateFormat})
		  ,OB_TIME = #{obTime}
		  ,AR_DATE = CONVERT(DATE, #{arDate},  ${dateFormat})
		  ,AR_TIME = #{arTime}


