/* MasterOrderMapper.updatePodBlNo : 오더의 비엘번호 변경시 POD의 비엘번호 업데이트 */
	UPDATE TB_ECM_POD SET BL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),''))) WHERE OD_JOB_NO = #{odJobNo};
