mapper.select:
/* MasterOrderMapper.selectUserInfo : 거래처정보조회 */ SELECT cus.CUSTOMER_CODE ,cus.CUSTOMER_NAME_ENG ,cus.ADDRESS_ENG ,cus.ADDRESS_A_ENG ,cus.ADDRESS_B_ENG ,cus.ATTN_ENG ,cus.TEL_ENG ,cus.FAX_ENG ,cus.AMS_STREET ,cus.AMS_ZIPCODE ,cus.AMS_STATE_CODE ,cus.AMS_COUNTRY_CODE ,cus.AMS_PLACE
,(SELECT BUSINESS_ID FROM VTB_SMS_BUSINESS_REG_INFO WHERE ENT_CODE = cus.ENT_CODE AND REGISTRATION_CODE = cus.REGISTRATION_CODE) AS BUSINESS_ID ,(SELECT IATA_CODE FROM TB_SMS_CUSTOMER_FMS WHERE ENT_CODE = cus.ENT_CODE AND CUSTOMER_CODE = cus.CUSTOMER_CODE) AS IATA_CODE
FROM TB_ECM_OD od LEFT JOIN TB_SMS_CUSTOMER cus ON cus.ENT_CODE = od.ENT_CODE AND cus.CUSTOMER_CODE = od.CUST_CODE_LV1 WHERE od.OD_JOB_NO = #{odJobNo}
,bus.CURRENCY_CODE
,(SELECT USER_NAME_ENG FROM TB_SMS_USER WHERE ENT_CODE = bus.ENT_CODE AND USER_ID = #{registerUserId}) AS USER_NAME_ENG ,( SELECT CASE WHEN ISNULL(opt.SET_VALUE, '') = '' THEN optMaster.DEFAULT_VALUE ELSE opt.SET_VALUE END FROM exps_master.dbo.TB_SMS_ENT_BUS_OPTION optMaster LEFT JOIN TB_SMS_ENT_BUS_OPTION opt ON opt.SOLUTION = optMaster.SOLUTION AND opt.OPTION_CODE = optMaster.OPTION_CODE AND opt.ENT_CODE = bus.ENT_CODE AND opt.ENT_BUSINESS_CODE = bus.ENT_BUSINESS_CODE WHERE optMaster.SOLUTION = 'FMS' AND optMaster.OPTION_CODE = 'A34' ) AS SIGN_HIS_AGENT_TYPE
FROM TB_SMS_ENT_BUSINESS bus LEFT JOIN TB_SMS_CUSTOMER cus ON cus.ENT_CODE = bus.ENT_CODE AND cus.CUSTOMER_CODE = bus.CUSTOMER_CODE WHERE bus.ENT_CODE = #{entCode} AND bus.ENT_BUSINESS_CODE = #{entBusinessCode}

/* MasterOrderMapper.selectMasterOrderListCommon : 마스터오더조회팝업 리스트 */
SELECT cod.OD_JOB_NO ,obl.OBL_JOB_NO ,obl.MBL_NO ,obl.OB_DATE ,obl.AR_DATE ,obl.AR_DATE AS PO_DATE ,obl.ORIG_NAME ,obl.DEST_NAME FROM TB_COM_OBL obl INNER JOIN TB_COM_OD cod ON cod.OBL_JOB_NO = obl.OBL_JOB_NO
LEFT JOIN TB_ECM_OD od ON od.OD_JOB_NO = cod.OD_JOB_NO
WHERE cod.ENT_CODE = #{srchEntCode}
AND cod.SOLUTION = #{srchSolution}
AND cod.BL_TYPE_MH = #{srchBlTypeMh}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND cod.BOUND = 'AIR' AND cod.BOUND_TYPE = 'EXP' AND cod.BOUND = 'AIR' AND cod.BOUND_TYPE = 'IMP' AND cod.BOUND = 'SEA' AND cod.BOUND_TYPE = 'EXP' AND cod.BOUND = 'SEA' AND cod.BOUND_TYPE = 'IMP'
AND cod.BOUND = 'AIR' AND cod.BOUND_TYPE = 'IMP' AND cod.BOUND = 'AIR' AND cod.BOUND_TYPE = 'EXP' AND cod.BOUND = 'SEA' AND cod.BOUND_TYPE = 'IMP' AND cod.BOUND = 'SEA' AND cod.BOUND_TYPE = 'EXP'
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}

/* MasterOrderMapper.selectHouseComOrder : 생성된 하우스 리스트 */
	SELECT
		 od.HBL_NO
		 ,od.OD_JOB_NO
		 ,od.OBL_JOB_NO
	FROM TB_COM_OD od
	WHERE od.MBL_NO = #{mblNo}
	AND od.SOLUTION = #{solution}
	AND od.BOUND = #{bound}
	AND od.BOUND_TYPE = #{boundType}
	AND od.BL_TYPE_MH = 'H'

mapper.update:
/* MasterOrderMapper.updateHouseSrNo : 전자상거래 마스터오더 TB_COM_OD, TB_COM_OBL 저장 */
	UPDATE TB_COM_OD SET
		SR_NO = #{srNo}
	WHERE HBL_NO = #{hblNo}
	AND OD_JOB_NO = #{odJobNo}

	UPDATE TB_COM_OBL SET
		SR_NO = #{srNo}
		, MBL_JOB_NO = #{mblJobNo}
	WHERE HBL_NO = #{hblNo}
	AND OBL_JOB_NO = #{oblJobNo}
